#include <stdio.h>

int main(void)
{
    int minutes = 135;

    // Convert minutes into whole hours.
    int hours = minutes / 60;

    /* The input has already been validated as non-negative.
       Keep the remainder for the next display field. */
    int remainingMinutes = minutes % 60;

    printf("%d hours and %d minutes\n", hours, remainingMinutes);
    return 0;
}

